  insert into public.page_sections (page, key, label, sort_order, is_visible, can_hide, can_reorder, schema, content, published_at) values ('index', 'welcome', 'Welcome', 20, true, true, true, '[{"name":"commitments","label":"Commitments","type":"list","fields":[{"name":"title","label":"Title","type":"text"},{"name":"text","label":"Text","type":"text"}],"min":1,"max":12,"fixed":false},{"name":"heading","label":"Heading","type":"text"},{"name":"lede","label":"Introduction","type":"textarea"}]'::jsonb, '{"commitments":[{"title":"Doctor profiles you can read","text":"See each dentist''s listed qualifications before you visit."},{"title":"Treatments explained simply","text":"Plain-language guides to common dental treatments."},{"title":"Authentic feedback only","text":"Reviews will come only from verified patient sources."},{"title":"Consent comes first","text":"Patient photos and stories appear only with written permission."}],"heading":"Dental care, with a personal touch.","lede":"We want every patient to feel informed, comfortable and cared for. Explore our doctors, learn about treatments and contact us for your dental care needs."}'::jsonb, now()) on conflict do nothing;
