  insert into public.page_sections (page, key, label, sort_order, is_visible, can_hide, can_reorder, schema, content, published_at) values ('treatments', 'more', 'More treatments', 40, true, false, false, '[{"name":"heading","label":"Heading","type":"text"},{"name":"intro","label":"Introduction","type":"text"},{"name":"note","label":"Note","type":"textarea"}]'::jsonb, '{"heading":"More treatments","intro":"Other dental care listed for the clinic.","note":"Treatment availability and details must be confirmed with the clinic."}'::jsonb, now()) on conflict do nothing;
  insert into public.page_sections (page, key, label, sort_order, is_visible, can_hide, can_reorder, schema, content, published_at) values ('treatments', 'cta', 'Closing call to action', 50, true, true, false, '[{"name":"heading","label":"Heading","type":"text"},{"name":"text","label":"Text","type":"textarea"},{"name":"booking_label","label":"Booking button label","type":"text"},{"name":"booking_visible","label":"Show booking button","type":"boolean"},{"name":"whatsapp_label","label":"WhatsApp button label","type":"text"},{"name":"whatsapp_visible","label":"Show WhatsApp button","type":"boolean"}]'::jsonb, '{"heading":"Not sure which treatment you need?","text":"Book a general consultation. The dentist will examine your teeth and explain your options.","booking_label":"Book an Appointment","booking_visible":true,"whatsapp_label":"Chat on WhatsApp","whatsapp_visible":true}'::jsonb, now()) on conflict do nothing;
