  insert into public.page_sections (page, key, label, sort_order, is_visible, can_hide, can_reorder, schema, content, published_at) values ('doctors', 'cta', 'Closing call to action', 30, true, true, false, '[{"name":"heading","label":"Heading","type":"text"},{"name":"text","label":"Text","type":"textarea"},{"name":"booking_label","label":"Booking button label","type":"text"},{"name":"booking_visible","label":"Show booking button","type":"boolean"},{"name":"whatsapp_label","label":"WhatsApp button label","type":"text"},{"name":"whatsapp_visible","label":"Show WhatsApp button","type":"boolean"}]'::jsonb, '{"heading":"Ready to plan your visit?","text":"Send your preferred date and time through WhatsApp. The clinic will contact you to confirm your appointment.","booking_label":"Book an Appointment","booking_visible":true,"whatsapp_label":"Chat on WhatsApp","whatsapp_visible":true}'::jsonb, now()) on conflict do nothing;
  insert into public.page_sections (page, key, label, sort_order, is_visible, can_hide, can_reorder, schema, content, published_at) values ('why-us', 'page_head', 'Page heading', 10, true, false, false, '[{"name":"heading","label":"Heading","type":"text"},{"name":"lede","label":"Introduction","type":"textarea"}]'::jsonb, '{"heading":"Care built around your needs","lede":"Understand our approach to dental care. Specific claims will be published only after the clinic confirms them."}'::jsonb, now()) on conflict do nothing;
  insert into public.page_sections (page, key, label, sort_order, is_visible, can_hide, can_reorder, schema, content, published_at) values ('why-us', 'approach', 'What you can expect', 20, true, false, false, '[{"name":"items","label":"Items","type":"list","fields":[{"name":"title","label":"Title","type":"text"},{"name":"text","label":"Text","type":"rich"}],"min":1,"max":12,"fixed":false},{"name":"heading","label":"Heading","type":"text"},{"name":"lede","label":"Introduction","type":"textarea"}]'::jsonb, '{"items":[{"title":"Experienced dental care","text":"Learn about the doctors’ verified qualifications and professional experience on their [profile pages](doctors.html)."},{"title":"A patient-first approach","text":"Understand your options and discuss treatment choices with the clinic before anything begins."},{"title":"Hygiene and sterilisation","text":"Clinic sterilisation practices and protocols will be described here after confirmation."},{"title":"Clear treatment guidance","text":"Ask the clinic about treatment plans, costs and what to expect before proceeding."}],"heading":"What you can expect from us","lede":"These are the standards the clinic can explain to patients at every visit."}'::jsonb, now()) on conflict do nothing;
  insert into public.page_sections (page, key, label, sort_order, is_visible, can_hide, can_reorder, schema, content, published_at) values ('why-us', 'cta', 'Closing call to action', 30, true, true, false, '[{"name":"heading","label":"Heading","type":"text"},{"name":"text","label":"Text","type":"textarea"},{"name":"booking_label","label":"Booking button label","type":"text"},{"name":"booking_visible","label":"Show booking button","type":"boolean"},{"name":"whatsapp_label","label":"WhatsApp button label","type":"text"},{"name":"whatsapp_visible","label":"Show WhatsApp button","type":"boolean"}]'::jsonb, '{"heading":"Have a question about your dental care?","text":"Contact the clinic to discuss your needs and available treatment options.","booking_label":"Book an Appointment","booking_visible":true,"whatsapp_label":"Chat on WhatsApp","whatsapp_visible":true}'::jsonb, now()) on conflict do nothing;
  insert into public.page_sections (page, key, label, sort_order, is_visible, can_hide, can_reorder, schema, content, published_at) values ('clinic', 'intro', 'Clinic introduction', 10, true, false, false, '[{"name":"facts","label":"Quick facts","type":"list","fields":[{"name":"label","label":"Label","type":"text"},{"name":"value","label":"Value","type":"text"}],"min":1,"max":12,"fixed":false},{"name":"heading","label":"Heading","type":"text"},{"name":"lede","label":"Introduction","type":"textarea"},{"name":"image","label":"Image","type":"image","alt_from_media":false},{"name":"image_alt","label":"Image description (alt text)","type":"text"},{"name":"caption_name","label":"Image caption (name)","type":"text"},{"name":"caption_role","label":"Image caption (role)","type":"text"}]'::jsonb, '{"facts":[{"label":"Location","value":"Devaraj Nagar, Saligramam, Chennai"},{"label":"Dental team","value":"Three doctors, led by Dr. K. R. Srinivasan"},{"label":"Open","value":"Monday to Saturday (timings to be confirmed)"}],"heading":"A neighbourhood dental clinic in Saligramam","lede":"Sri Danvantari Dental Care offers dental care for you and your family on Navalar Main Road, near Shankar Narayanan Temple.","image":"cfc5de5d-10e2-dbd7-d451-2d2881598b9f","image_alt":"Dr. K. R. Srinivasan at Sri Danvantari Dental Care","caption_name":"Dr. K. R. Srinivasan","caption_role":"Lead doctor"}'::jsonb, now()) on conflict do nothing;
  insert into public.page_sections (page, key, label, sort_order, is_visible, can_hide, can_reorder, schema, content, published_at) values ('clinic', 'approach', 'How we approach your care', 20, true, false, false, '[{"name":"items","label":"Items","type":"list","fields":[{"name":"title","label":"Title","type":"text"},{"name":"text","label":"Text","type":"textarea"}],"min":1,"max":12,"fixed":false},{"name":"heading","label":"Heading","type":"text"},{"name":"intro","label":"Introduction","type":"text"}]'::jsonb, '{"items":[{"title":"Listen first","text":"Every visit starts with your concerns, your history and what you would like to achieve."},{"title":"Explain clearly","text":"You hear what we find and what your options are, in plain language, before any treatment begins."},{"title":"Decide together","text":"Treatment plans, visits and costs are discussed openly so you can choose with confidence."}],"heading":"How we approach your care","intro":"Simple principles that guide every consultation."}'::jsonb, now()) on conflict do nothing;
  insert into public.page_sections (page, key, label, sort_order, is_visible, can_hide, can_reorder, schema, content, published_at) values ('clinic', 'steps', 'What to expect at your visit', 30, true, false, false, '[{"name":"items","label":"Items","type":"list","fields":[{"name":"title","label":"Title","type":"text"},{"name":"text","label":"Text","type":"textarea"}],"min":1,"max":12,"fixed":false},{"name":"heading","label":"Heading","type":"text"},{"name":"intro","label":"Introduction","type":"text"}]'::jsonb, '{"items":[{"title":"Send an enquiry","text":"Book through the website or WhatsApp. The clinic contacts you to confirm a time."},{"title":"Consultation","text":"Share your concerns and medical history, then the dentist examines your teeth and gums."},{"title":"Your options","text":"The dentist explains what they found and the treatment choices available."},{"title":"Treatment and review","text":"Treatment goes ahead once you agree, with follow-up visits where needed."}],"heading":"What to expect at your visit","intro":"A typical first appointment, step by step."}'::jsonb, now()) on conflict do nothing;
  insert into public.page_sections (page, key, label, sort_order, is_visible, can_hide, can_reorder, schema, content, published_at) values ('clinic', 'prepare', 'Before you come in', 40, true, false, false, '[{"name":"items","label":"Items","type":"list","fields":[{"name":"title","label":"Title","type":"text"},{"name":"text","label":"Text","type":"textarea"}],"min":1,"max":12,"fixed":false},{"name":"heading","label":"Heading","type":"text"},{"name":"lede","label":"Introduction","type":"textarea"}]'::jsonb, '{"items":[{"title":"Bring previous records","text":"Earlier dental X-rays, reports or prescriptions, if you have them."},{"title":"List your medicines","text":"Include any medical conditions and allergies, so the dentist can plan safely."},{"title":"Note your symptoms","text":"When the problem started, what makes it better or worse, and any swelling."},{"title":"Confirm your time","text":"Your appointment is confirmed only when the clinic contacts you."}],"heading":"Before you come in","lede":"A few simple steps help the dentist understand your needs at the first visit."}'::jsonb, now()) on conflict do nothing;
  insert into public.page_sections (page, key, label, sort_order, is_visible, can_hide, can_reorder, schema, content, published_at) values ('clinic', 'urgent', 'Urgent symptoms note', 50, true, true, false, '[{"name":"title","label":"Title","type":"text"},{"name":"text","label":"Text","type":"textarea"}]'::jsonb, '{"title":"Urgent symptoms?","text":"Severe facial swelling, difficulty breathing or swallowing, bleeding that will not stop or a facial injury need urgent medical care. Go to the nearest hospital emergency department or call 108 / 112."}'::jsonb, now()) on conflict do nothing;
