  insert into public.treatment_categories (id, name, slug, sort_order) values ('18be280d-5d6f-ad60-e03d-9df6e9ae81df', 'Gum care', 'gum-care', 60) on conflict do nothing;
  insert into public.treatments (id, slug, title, category_id, display, show_on_home, card_summary, description, consult_questions, image_id, image_alt, booking_value, cta_label, sort_order, status) values ('32b94656-10a1-08a6-3652-f3dd15c0d2f0', 'implants', 'Dental Implants', '3b57c845-c3f4-22de-7dfc-79bef32c7d85', 'featured', true, 'A small post placed in the jaw supports a replacement tooth. Ask whether implants suit your situation.', 'A dental implant replaces a missing tooth. A small post is placed in the jawbone, and once it has settled, a crown is fixed on top so the new tooth looks and works like a natural one.', array['Is an implant suitable for the gap I have?','What other options are there, such as a bridge or denture?','How many visits are usually involved?']::text[], '2a88cad9-9ac9-5148-ff6d-ae346da86978', 'Illustration of a dental implant: a crown attached to an implant post in the jaw', 'Dental implants', 'Ask about this treatment', 10, 'published') on conflict do nothing;
  insert into public.treatments (id, slug, title, category_id, display, show_on_home, card_summary, description, consult_questions, image_id, image_alt, booking_value, cta_label, sort_order, status) values ('0e6c277e-201c-6135-582c-1fe5703810d9', 'root-canal', 'Root Canal Treatment', '76d33ef3-b9b5-d0ed-7852-a348586eafc8', 'featured', true, 'Treats an infected or inflamed nerve inside a tooth so the natural tooth can be kept.', 'Root canal treatment deals with infection or inflammation of the pulp, the soft tissue inside a tooth. The canals are cleaned, shaped and sealed, and the tooth is usually protected with a filling or crown afterwards.', array['What symptoms should I mention at my visit?','Will the tooth need a crown afterwards?','How should I care for the tooth between visits?']::text[], '2cd90380-56f7-f738-e32a-9e86350de53e', 'Illustration of root canal treatment: a tooth cross-section showing the pulp and root canals', 'Root canal treatment', 'Ask about this treatment', 20, 'published') on conflict do nothing;
  insert into public.treatments (id, slug, title, category_id, display, show_on_home, card_summary, description, consult_questions, image_id, image_alt, booking_value, cta_label, sort_order, status) values ('0a8d88da-bf72-8127-4e45-c9641d0d7f67', 'braces', 'Braces & Clear Aligners', '5782c7dd-69fc-c44d-c26e-d5ee3edbeb51', 'featured', true, 'Brackets and wires, or a series of clear removable trays, gradually move teeth into place.', 'Orthodontic treatment straightens teeth and improves how they meet. Fixed braces use brackets and a wire; clear aligners are a series of removable trays changed over time. Both need regular review visits.', array['Is orthodontic treatment available at the clinic?','Which option fits my teeth and routine?','How often are review visits needed?']::text[], '4f43c0ac-c16b-3a39-3c06-6ad4d86f052f', 'Illustration of braces with brackets and a wire, and a clear aligner tray below', 'Braces and aligners', 'Ask about this treatment', 30, 'published') on conflict do nothing;
  insert into public.treatments (id, slug, title, category_id, display, show_on_home, card_summary, description, consult_questions, image_id, image_alt, booking_value, cta_label, sort_order, status) values ('f4d8ea6e-127a-114c-732c-8133b09f3dcb', 'whitening', 'Teeth Whitening', 'e4d09143-3358-9151-ccfe-090ff6c55d04', 'featured', true, 'Professional lightening of tooth shade, planned after a check of your teeth and gums.', 'Professional whitening lightens the natural shade of teeth. A dentist first checks your teeth and gums, since existing fillings or crowns do not change colour, then explains what can realistically be expected.', array['Are my teeth and gums suitable for whitening?','Will my fillings or crowns match afterwards?','How can I keep the result longer?']::text[], '73a0f32b-8399-cfda-9b05-04fe0dcac2ed', 'Illustration of teeth whitening: a tooth beside a shade guide', 'Teeth whitening', 'Ask about this treatment', 40, 'published') on conflict do nothing;
  insert into public.treatments (id, slug, title, category_id, display, show_on_home, card_summary, description, consult_questions, image_id, image_alt, booking_value, cta_label, sort_order, status) values ('f9d17998-0678-dbe2-1341-b5c1dd94005d', 'smile-design', 'Smile Designing', 'e4d09143-3358-9151-ccfe-090ff6c55d04', 'featured', true, 'Planning changes to the shape, shade or alignment of teeth before any treatment starts.', 'Smile designing is a planning step. Your dentist looks at the shape, size, shade and alignment of your teeth in relation to your face and smile, then discusses which treatments could help you reach your goals.', array['What would you change, and why?','Which treatments would be involved?','Can I see the plan before deciding?']::text[], 'b6b1b79d-3e5d-a071-eb81-13a59d846f2f', 'Illustration of smile designing: a smile with proportion guide lines', 'Smile designing', 'Ask about this treatment', 50, 'published') on conflict do nothing;
  insert into public.treatments (id, slug, title, category_id, display, show_on_home, card_summary, description, consult_questions, image_id, image_alt, booking_value, cta_label, sort_order, status) values ('8bdeb7bc-5d19-8850-7b82-81898d3b8fae', 'crowns-bridges', 'Crowns & Bridges', '76d33ef3-b9b5-d0ed-7852-a348586eafc8', 'featured', true, 'A crown protects a weakened tooth; a bridge replaces a missing tooth using its neighbours.', 'A crown is a cap that covers and strengthens a damaged or weakened tooth. A bridge replaces one or more missing teeth by attaching false teeth to crowns on the teeth either side of the gap.', array['Does my tooth need a crown or a filling?','What materials are available?','How do I clean around a bridge?']::text[], '1ffbaf3a-c50f-7c77-84da-2d1582ab5d17', 'Illustration of a dental bridge across three teeth and a crown being placed over a prepared tooth', 'Crowns and bridges', 'Ask about this treatment', 60, 'published') on conflict do nothing;
  insert into public.treatments (id, slug, title, category_id, display, card_summary, booking_value, cta_label, sort_order, status) values ('193f3d6f-aec1-e2b3-68b5-0af2e3c76dcb', 'pediatric-dentistry', 'Pediatric Dentistry', 'fedb53e3-4c46-6596-d094-69c0b2e5c5b0', 'more', 'Contact the clinic to confirm dental services for children.', 'Children''s dental care', 'Ask about this treatment', 70, 'published') on conflict do nothing;
