  insert into public.doctors (id, slug, name, initials, qualifications, designation, card_text, bio, photo_id, photo_alt, photo_placeholder, legacy_page, seo_title, seo_description, sort_order, status) values ('8e0f6b03-2bb2-1b5a-0762-269cca22b19c', 'dr-samyukta', 'Dr. Samyukta', 'S', '', 'Professional details pending', 'Profile information and an original photograph will be added when provided by the clinic.', 'Dr. Samyukta is listed as a member of the clinic’s dental team. The photograph, qualification, specialisation, experience and other professional details will be added after the clinic provides and verifies them.
  insert into public.testimonials (id, author_name, initials, quote, label, source, review_age, consent_basis, consent_note, sort_order, status) values ('3fc6ba12-4f41-cf73-8f61-b568f13686c1', 'Vikraman Vasudevan', 'VV', 'Dr. Srinivasan and Dr. Krupa Rani were excellent in giving me treatment. They were highly professional, and their sincerity and commitment were top notch. Highly recommended.', 'Patient feedback · 3 months ago', 'Google Business Profile (screenshot supplied by the clinic)', 0, 'public_google_review', 'Imported from the existing website. Public Google review supplied by the clinic owner; confirm the clinic is happy to display it.', 10, 'published') on conflict do nothing;
