  insert into public.testimonials (id, author_name, initials, quote, label, source, review_age, consent_basis, consent_note, sort_order, status) values ('c3082255-9ef5-42a8-3b95-087e898dbc41', 'Abdul Rahuman', 'AR', 'The way of handling was so humble and they take care of it.', 'Patient feedback · 1 year ago', 'Google Business Profile (screenshot supplied by the clinic)', 1, 'public_google_review', 'Imported from the existing website. Public Google review supplied by the clinic owner; confirm the clinic is happy to display it.', 50, 'published') on conflict do nothing;
  insert into public.testimonials (id, author_name, initials, quote, label, source, review_age, consent_basis, consent_note, sort_order, status) values ('afab7da1-8a80-e69b-3639-19b552ca5df2', 'Venkatesh Balivada', 'VB', 'Recently I visited Sri Danvantari Dental Care. I am very happy and pleased with his work. He is very smart, his work is excellent, and he always knows what is best for his patients. I recommend him to everyone.', 'Patient feedback · 7 years ago', 'Google Business Profile (screenshot supplied by the clinic)', 7, 'public_google_review', 'Imported from the existing website. Public Google review supplied by the clinic owner; confirm the clinic is happy to display it.', 60, 'published') on conflict do nothing;
