  insert into public.testimonials (id, author_name, initials, quote, label, source, review_age, consent_basis, consent_note, sort_order, status) values ('6aec9d44-84b5-918e-b9ae-3e6df5b59582', 'Mani Shankar', 'MS', 'Due to a heavy toothache, I asked for an almost impossible appointment. Thankfully, they made an appointment. Treatments are good.', 'Patient feedback', 'Google Business Profile (screenshot supplied by the clinic)', 99, 'public_google_review', 'Imported from the existing website. Public Google review supplied by the clinic owner; confirm the clinic is happy to display it.', 100, 'published') on conflict do nothing;
