  insert into public.gallery_items (id, gallery, media_id, title, caption, alt_text, sort_order, status) values ('410499a5-5d37-6b1c-2f83-751ad3aa2780', 'cases', '15fbb758-e7a4-9c7d-e9db-01fabf9ce6a8', 'Smile restoration example', 'Ask the dentist which options may suit your needs.', 'Before-and-after smile restoration example shared by the clinic', 10, 'published') on conflict do nothing;
  insert into public.gallery_items (id, gallery, media_id, title, caption, alt_text, sort_order, status) values ('2c9a863b-e5fb-ba47-0994-a1d5e7b4cf36', 'cases', '495d9169-eecb-2880-f6ad-8bc7fd74b6a2', 'Bridge treatment steps', 'Your dentist will explain the process and alternatives.', 'Illustrated sequence showing a missing-teeth case and dental bridge restoration', 20, 'published') on conflict do nothing;
  insert into public.gallery_items (id, gallery, media_id, title, caption, alt_text, sort_order, status) values ('490987c1-ecaf-a51a-2929-de5ef612b9c8', 'cases', '29211e7f-2ea9-429b-bed6-e12c4c4853a8', 'Dental treatment example', 'Clinical suitability and expected outcomes vary by patient.', 'Before-and-after dental case example shared by the clinic', 30, 'published') on conflict do nothing;
  insert into public.faqs (id, page, question, answer, sort_order, status) values ('93d3d02e-486b-cfa9-9d14-e197167b9500', 'contact', 'How do I book an appointment?', 'Use Book an Appointment on any page. Fill in your name, mobile number and preferred date, and your request opens in WhatsApp. Press Send, and the clinic will contact you to confirm a time.', 10, 'published') on conflict do nothing;
  insert into public.faqs (id, page, question, answer, sort_order, status) values ('a8d4d82e-604f-ff2b-29b2-a5df2ac30d30', 'contact', 'What are the clinic timings?', 'The current reference timings are Monday to Saturday, 10:00 am–12:00 pm and 6:30–9:00 pm. These are provisional, so please confirm with the clinic before visiting.', 20, 'published') on conflict do nothing;
  insert into public.faqs (id, page, question, answer, sort_order, status) values ('4dfb79fa-ffff-1c46-9a84-8001d96845dd', 'contact', 'Where exactly is the clinic?', 'No. 24, Navalar Main Road, Devaraj Nagar, near Shankar Narayanan Temple, Saligramam, Chennai, Tamil Nadu 600093. Use Get directions to open the location in Google Maps.', 30, 'published') on conflict do nothing;
  insert into public.faqs (id, page, question, answer, sort_order, status) values ('2a10c3b9-85b7-2bda-a1ff-6ef3ab109420', 'contact', 'Which treatments are available?', 'The clinic lists general consultations, implants, root canal treatment, crowns and bridges, fillings, extractions, dentures and more. See the [Treatments](treatments.html) page and confirm availability when you book.', 40, 'published') on conflict do nothing;
  insert into public.faqs (id, page, question, answer, sort_order, status) values ('7098ad28-8219-0ee3-faa8-2c75d44bc401', 'contact', 'Is my information stored by this website?', 'When you send the booking form, your name, mobile number, preferred date and time, treatment and message are stored securely so the clinic can follow up. Only authorised clinic staff can see them. The form also prepares a WhatsApp message on your device; nothing is sent through WhatsApp until you press Send there. The Chat with Us help desk works entirely in your browser and does not send or store your messages.', 50, 'published') on conflict do nothing;
  insert into public.faqs (id, page, question, answer, sort_order, status) values ('2036e9c9-56c7-974e-86cb-e43cf04fc0a3', 'contact', 'What should I bring to my first visit?', 'If you have them, bring previous dental records or X-rays, a list of the medicines you take, and details of any medical conditions or allergies. Arriving a few minutes early gives time to share this with the dentist.', 60, 'published') on conflict do nothing;
  insert into public.faqs (id, page, question, answer, sort_order, status) values ('7f297d6b-4daf-2c36-9969-62557f3fdbb6', 'contact', 'Are treatment fees listed on the website?', 'No. Fees are not published here because they depend on an examination and your treatment plan. Please ask the clinic when you book.', 70, 'published') on conflict do nothing;
  insert into public.faqs (id, page, question, answer, sort_order, status) values ('70101b49-4785-e9e1-2637-d31072e25701', 'contact', 'Is my appointment confirmed when I send the form?', 'No. The form prepares a request in WhatsApp. Your appointment is confirmed only when the clinic contacts you.', 80, 'published') on conflict do nothing;
  insert into public.faqs (id, page, question, answer, sort_order, status) values ('5b46f948-33f4-5182-37b4-25f3244f3303', 'contact', 'What should I do in a dental emergency?', 'If you have severe facial swelling, swelling spreading towards the eye or neck, difficulty breathing or swallowing, bleeding that will not stop, a high fever with dental pain, or a facial injury, seek urgent medical care straight away at the nearest hospital emergency department, or call 108 (ambulance) or 112 (emergency). Do not wait for an appointment request.', 90, 'published') on conflict do nothing;
  insert into public.faqs (id, page, question, answer, sort_order, status) values ('7e0d42b5-596f-0f65-5aad-50b563234373', 'contact', 'Is the Chat with Us assistant a dentist?', 'No. It is an automated help desk with set answers about the clinic and general dental care. It cannot diagnose, prescribe, quote fees or book appointments.', 100, 'published') on conflict do nothing;
